import java.util.*;
import java.math.BigInteger;

public class Main {
    static final int MOD = 1000000007;

    static int modPow(int base, int exp) {
        long res = 1;
        long b = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * b) % MOD;
            }
            b = (b * b) % MOD;
            e >>= 1;
        }
        return (int) res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int[][] prob = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = sc.nextInt();
                // Convert percentage to modular probability
                prob[i][j] = (int) ((long) val * modPow(100, MOD - 2) % MOD);
            }
        }

        // Precompute group sizes and subset lists
        List<List<Integer>> groupSizes = new ArrayList<>();
        List<List<Integer>> subsetList = new ArrayList<>();
        for (int size = 0; size <= n; size++) {
            groupSizes.add(new ArrayList<>(Collections.nCopies(1 << n, 0)));
            subsetList.add(new ArrayList<>());
        }

        for (int size = 0; size <= n; size++) {
            List<Integer> groupSizeArr = groupSizes.get(size);
            List<Integer> subsetArr = subsetList.get(size);
            for (int s = 0; s < (1 << n); s++) {
                if (Integer.bitCount(s) == size) {
                    groupSizeArr.set(s, subsetArr.size());
                    subsetArr.add(s);
                }
            }
        }

        // Initialize DP array
        Map<Long, Integer>[] dp = new HashMap[n + 1];
        for (int i = 0; i <= n; i++) {
            dp[i] = new HashMap<>();
        }
        dp[0].put(1L, 1);

        for (int i = 1; i <= n; i++) {
            Map<Long, Integer> prevDP = dp[i - 1];
            Map<Long, Integer> currDP = dp[i];

            for (int s = 0; s < (1 << n); s++) {
                long productProb = 1;
                for (int j = 0; j < n; j++) {
                    if (((s >> j) & 1) == 1) {
                        productProb = (productProb * prob[i - 1][j]) % MOD;
                    } else {
                        productProb = (productProb * (1 + MOD - prob[i - 1][j])) % MOD;
                    }
                }

                for (Map.Entry<Long, Integer> entry : prevDP.entrySet()) {
                    long f = entry.getKey();
                    int count = entry.getValue();

                    long mask = 0;
                    List<Integer> subsetSizes = groupSizes.get(i);
                    List<Integer> subsetArr = subsetList.get(i);
                    for (int t : subsetArr) {
                        for (int j = 0; j < n; j++) {
                            if (((t >> j) & 1) == 1 && ((s >> j) & 1) == 1) {
                                int prevGroupSizeIndex = groupSizes.get(i - 1).get(t ^ (1 << j));
                                if (((f >> prevGroupSizeIndex) & 1) == 1) {
                                    mask |= 1L << groupSizes.get(i).get(t);
                                    break;
                                }
                            }
                        }
                    }
                    long newMask = mask;
                    int existing = currDP.getOrDefault(newMask, 0);
                    long newVal = (long) count * productProb % MOD;
                    currDP.put(newMask, (int) ((existing + newVal) % MOD));
                }
            }
        }

        System.out.println(dp[n].getOrDefault(1L, 0));
        sc.close();
    }
}
